namespace ghidra.app.plugin.core.decompile.actions;

using docking;
using docking.action;
using docking.action;
using docking.options;
using ghidra.app.util;
using ghidra.framework.plugintool;
using ghidra.util;

public class EditPropertiesAction : DockingAction {
	private static string OPTIONS_TITLE = "Decompiler";

	private PluginTool tool;

	public EditPropertiesAction(string owner, PluginTool tool) : base("DecompilerProperties", owner)
    {
		this.tool = tool;
		setHelpLocation(new HelpLocation(HelpTopics.DECOMPILER, "DisplayOptions"));
		setPopupMenuData( new MenuData( new string[]{ "Properties"}, "ZED" ) );
	}
	
	/* @Override */
	public bool isEnabledForContext(ActionContext context) {
		return tool.getService(typeof(OptionsService)) != null;
	}
	
	/* @Override */
	public void actionPerformed(ActionContext context) {
        OptionsService service = tool.getService( typeof(OptionsService) );
        service.showOptionsDialog( OPTIONS_TITLE  + ".Display", "Decompiler" );
	}
	
}
